/** Components with no brand mark fall back to a lucide name instead.
 *  @type {Record<string, { icon: string, colour: string }>} */
const LUCIDE = {
  mkcert: { icon: "lucide:ShieldCheck", colour: "#4c8bf5" },
  // The scheduler is ours, not a project with a logo, so it takes a glyph.
  cron: { icon: "lucide:CalendarClock", colour: "#8b7fd4" },
};

const FALLBACK = { icon: "lucide:Box", colour: "var(--muted-foreground)" };

/**
 * The mark for a component.
 *
 * Returns either `{ path, colour }` for a brand logo or `{ icon, colour }` for
 * a lucide name, and `ui/el.js` renders whichever it was handed. Keeping both
 * shapes behind one lookup means a view never has to know which kind a
 * component has.
 *
 * @param {string} id
 * @returns {{ path?: string, icon?: string, colour: string }}
 */
export function markFor(id) {
  return MARKS[id] ?? LUCIDE[id] ?? FALLBACK;
}
